public int minOperations(int n) {
    // The array is [1, 3, 5, ..., 2n-1]
    // The target value to make all elements equal is the average, which is n
    // (since the sum is n^2 and there are n elements, average = n)
    // We need to compute the minimum number of operations.
    // Each operation moves 1 unit from one element to another.
    // The total number of operations is the sum of the absolute differences between each element and the target, divided by 2.
    // Because each operation reduces the total "excess" by 1 on one side and increases the "deficit" by 1 on the other,
    // so the total operations = (sum of |arr[i] - n|) / 2.

    // arr[i] = 2*i + 1
    // |arr[i] - n| = |2*i + 1 - n|

    // We can compute this sum directly.
    long totalDiff = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        totalDiff += Math.abs(val - n);
    }

    return (int)(totalDiff / 2);
}
