public int maxUniqueSplit(String s) {
    int n = s.length();
    java.util.Set<String> used = new java.util.HashSet<>();
    int max = 0;

    // Backtracking function
    // index: current position in the string
    // count: number of unique substrings formed so far
    void backtrack(int index, int count) {
        if (index == n) {
            max = Math.max(max, count);
            return;
        }

        // Pruning: if the remaining characters cannot exceed the current max, stop
        // The maximum possible additional substrings is (n - index)
        if (count + (n - index) <= max) {
            return;
        }

        for (int end = index; end < n; end++) {
            String sub = s.substring(index, end + 1);
            if (!used.contains(sub)) {
                used.add(sub);
                backtrack(end + 1, count + 1);
                used.remove(sub);
            }
        }
    }

    backtrack(0, 0);
    return max;
}

