public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    Queue<Integer> queue = new LinkedList<>();

    // Start with single digit numbers 0-9
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }

        // Generate next stepping numbers
        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            int next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    // Sort the result to ensure ascending order
    Collections.sort(result);
    return result;
