public static boolean isBoomerang(int[][] points) {
    // A boomerang is a set of three distinct points that are not collinear.
    // We can check if the three points are collinear by checking if the area of the triangle formed by them is zero.
    // The area of a triangle with vertices (x1, y1), (x2, y2), (x3, y3) is:
    // 0.5 * |x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2)|
    // If the area is zero, the points are collinear, so it's not a boomerang.

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the cross product (which is twice the signed area)
    // If the cross product is zero, the points are collinear
    int crossProduct = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);

    // If the cross product is not zero, the points are not collinear, so they form a boomerang
    return crossProduct != 0;
}
