        if (next2 == nextUgly) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (next3 == nextUgly) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (next5 == nextUgly) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }

    return ugly[n - 1];
}
