public static int calculateUniqueSum(int[] nums) {
    java.util.Set<Integer> seen = new java.util.HashSet<>();
    java.util.Set<Integer> unique = new java.util.HashSet<>();
    for (int num : nums) {
        if (seen.contains(num)) {
            unique.remove(num);
        } else {
            seen.add(num);
            unique.add(num);
        }
    }
    int sum = 0;
    for (int num : unique) {
        sum += num;
    }
    return sum;
}
